<!doctype html><html><head><meta charset="utf-8"><title>Receipt <?= esc($sale['sale_no']) ?></title><style>body{font-family:Arial,sans-serif;width:80mm;margin:0 auto;font-size:12px}.row{display:flex;justify-content:space-between}table{width:100%;border-collapse:collapse}th,td{padding:3px 0;border-bottom:1px dotted #999}.right{text-align:right}.total{font-size:16px;font-weight:bold;margin-top:8px}@media print{button{display:none}}</style></head><body><h3 style="text-align:center;margin-bottom:4px">Perfect LPG</h3><div style="text-align:center">SALE RECEIPT</div><hr><div class="row"><span>No.</span><span><?= esc($sale['sale_no']) ?></span></div><div class="row"><span>Date</span><span><?= esc($sale['transaction_at']) ?></span></div><div>Customer: <?= esc($sale['customer_name']??'Walk-in / Cash') ?></div><hr><table><thead><tr><th>Item</th><th class="right">Qty</th><th class="right">Rate</th><th class="right">Amount</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= esc($i['line_type']) ?></td><td class="right"><?= esc($i['quantity']) ?></td><td class="right"><?= number_format((float)$i['applied_rate'],2) ?></td><td class="right"><?= number_format((float)$i['line_total'],2) ?></td></tr><?php endforeach; ?></tbody></table><div class="row"><span>Subtotal</span><span><?= number_format((float)$sale['subtotal'],2) ?></span></div><div class="row"><span>Discount</span><span><?= number_format((float)$sale['discount_amount'],2) ?></span></div><div class="row total"><span>Total</span><span>Rs. <?= number_format((float)$sale['total_amount'],2) ?></span></div><?php foreach($payments as $p): ?><div class="row"><span><?= esc(ucfirst($p['payment_mode'])) ?></span><span>Rs. <?= number_format((float)$p['amount'],2) ?></span></div><?php endforeach; ?><hr><div style="text-align:center">Thank you</div><button onclick="window.print()">Print</button></body></html>